import{_ as n,H as t,f as r,i}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"35 | [视频]实际项目中的性能优化：ingress-nginx中的几个PR解读","description":"","frontmatter":{},"headers":[{"level":2,"title":"今日核心","slug":"今日核心","link":"#今日核心","children":[]},{"level":2,"title":"课件参考","slug":"课件参考","link":"#课件参考","children":[]}],"relativePath":"OpenResty从入门到实战/35-［视频］实际项目中的性能优化：ingress-nginx中的几个PR解读.md","filePath":"OpenResty从入门到实战/35-［视频］实际项目中的性能优化：ingress-nginx中的几个PR解读.md","lastUpdated":null}'),s={name:"OpenResty从入门到实战/35-［视频］实际项目中的性能优化：ingress-nginx中的几个PR解读.md"};function a(l,e,p,g,_,o){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="_35-视频-实际项目中的性能优化-ingress-nginx中的几个pr解读" tabindex="-1">35 | [视频]实际项目中的性能优化：ingress-nginx中的几个PR解读 <a class="header-anchor" href="#_35-视频-实际项目中的性能优化-ingress-nginx中的几个pr解读" aria-label="Permalink to &quot;35 | [视频]实际项目中的性能优化：ingress-nginx中的几个PR解读&quot;">​</a></h1><p>你好，我是温铭。</p><p>今天的内容，我同样会以视频的形式来讲解。老规矩，在你进行视频学习之前，先问你这么几个问题：</p><ul><li>如何在开源项目中找到可能存在的性能问题？</li><li>在 Github 上，如何与其他开发者正确地交流？</li></ul><p>这几个问题，也是今天视频课要解决的核心内容，希望你可以先自己思考一下，并带着问题来学习今天的视频内容。</p><p>同时，我会给出相应的文字介绍，方便你在听完视频内容后，及时总结与复习。下面是今天这节课的文字介绍部分。</p><h2 id="今日核心" tabindex="-1">今日核心 <a class="header-anchor" href="#今日核心" aria-label="Permalink to &quot;今日核心&quot;">​</a></h2><p><a href="https://github.com/kubernetes/ingress-nginx" target="_blank" rel="noreferrer">ingress-nginx</a> 是 k8s 官方的一个项目，主要使用Go、 Nginx 和 lua-nginx-module 来处理入口流量。</p><p>在今天的视频中，我会为你清楚介绍，如何运用我们刚刚学习的性能优化方面的知识，来发现开源项目的性能问题。要知道，在我们给开源项目贡献 PR 时，跑通测试案例集以及与项目维护者积极沟通，都是非常重要的。</p><p>下面是 ingress-nginx 中，和 OpenResty 性能相关的两个 PR：</p><ul><li><a href="https://github.com/kubernetes/ingress-nginx/pull/3673" target="_blank" rel="noreferrer">https://github.com/kubernetes/ingress-nginx/pull/3673</a></li><li><a href="https://github.com/kubernetes/ingress-nginx/pull/3674" target="_blank" rel="noreferrer">https://github.com/kubernetes/ingress-nginx/pull/3674</a></li></ul><p>从中你也可以发现，即使是资深的开发者，对 LuaJIT 相关的优化，可能也并不是很熟悉。一方面是因为，这两个 PR 涉及到的代码，并不会对整体系统造成严重的性能下降；另一个方面，这方面的优化知识，没有人系统地总结过，开发者即使想优化也找不到方向。</p><p>事实上，很多时候，我们站在代码可读性和可维护性的角度来看，可有可无的优化是不必要的，你只要去优化那些被频繁执行的代码片段就可以了，过度优化是万恶之源。</p><p>那么，学完今天这节课后，你是否可以在其他的开源项目中，找到类似的性能优化点呢？</p><h2 id="课件参考" tabindex="-1">课件参考 <a class="header-anchor" href="#课件参考" aria-label="Permalink to &quot;课件参考&quot;">​</a></h2><p>今天的课件已经上传到了我的GitHub上，你可以自己下载学习。</p><p>链接如下： <a href="https://github.com/iresty/geektime-slides" target="_blank" rel="noreferrer">https://github.com/iresty/geektime-slides</a></p><p>如果有不清楚的地方，你可以在留言区提问，另也可以在留言区分享你的学习心得。期待与你的对话，也欢迎你把这篇文章分享给你的同事、朋友，我们一起交流、一起进步。</p>',18)])])}const c=n(s,[["render",a]]);export{h as __pageData,c as default};
